import {MODEL_ID,MODEL_VERSION,REGISTRY_ID,REGISTRY_VERSION} from '../../src/projects/definitions';import {REPOSITORY_DTO_VERSION,type ProjectMetadataSnapshot,type ProjectRevisionView,type CommitReceipt} from '../../src/projects/repository.dto';import {hasEntityIdShape} from '../../src/projects/compatibility';
import {metadata,inspectEAnswer,readEReply,own} from './e-test-response';
export interface ESessionBinding {readonly scope:string;readonly identity:object;readonly recovery:string;}
/** Trusted synthetic fixture cache ports only, not a real /me API or source of server authorization. */
export interface EFixturePort {readonly origin:string;readonly lookup:(token:string)=>ESessionBinding|null;readonly ready:()=>boolean;}
export type EPhase='EMPTY'|'LOADING'|'READY'|'COMMITTED'|'CONFLICT'|'UNKNOWN_OUTCOME'|'AUTH_REQUIRED'|'FORBIDDEN'|'UNAVAILABLE'|'INVALID_REQUEST'|'INVALID_RESPONSE'|'LIST_INVALIDATED'|'IGNORED';
const boundary={scope:'E_TEST_ONLY',metadataOnly:true,productionAuthority:'NOT_GRANTED',persistencePermission:'NOT_GRANTED',executionPermission:'NOT_GRANTED',trustedAdmission:'NOT_IMPLEMENTED',applyPermission:'NOT_GRANTED'} as const;
export interface EView extends Readonly<typeof boundary>{readonly phase:EPhase;readonly project:ProjectMetadataSnapshot|null;readonly projects:readonly ProjectMetadataSnapshot[]|null;readonly revisions:readonly ProjectRevisionView[]|null;readonly receipt:CommitReceipt|null;readonly cursor:string|null;}
function empty(phase:EPhase):EView{return Object.freeze({...boundary,phase,project:null,projects:null,revisions:null,receipt:null,cursor:null});}
interface Command {readonly scope:string;readonly operation:'create-project'|'update-metadata'|'soft-delete-project';readonly body:string;readonly key:string;readonly projectId:string|null;uncertain:boolean;}
const commands=new WeakMap<object,Command>();
const header={dtoVersion:REPOSITORY_DTO_VERSION,modelId:MODEL_ID,modelVersion:MODEL_VERSION,registry:{id:REGISTRY_ID,version:REGISTRY_VERSION}} as const;
export class EWorkspace {
 #token:string;#epoch=0;#request=0;#view:EView=empty('EMPTY');#binding:ESessionBinding|null=null;#active:AbortController|null=null;
 constructor(private readonly port:EFixturePort,token:string,private readonly timeoutMs=4000){if(!/^http:\/\/127\.0\.0\.1:[1-9][0-9]{0,4}$/.test(port.origin)||Number(new URL(port.origin).port)>65535||!Number.isInteger(timeoutMs)||timeoutMs<10||timeoutMs>4000)throw Error('E_TEST_PORT');this.#token=token;}
 session(token:string){this.#active?.abort();this.#token=token;this.#epoch++;this.#request++;this.#binding=null;this.#view=empty('AUTH_REQUIRED');}
 view():EView {const now=this.port.lookup(this.#token);if(this.#binding&&(!now||now.identity!==this.#binding.identity||now.scope!==this.#binding.scope)){this.#view=empty('AUTH_REQUIRED');this.#binding=null;}else if(this.#binding&&(!this.port.ready()||now?.recovery!==this.#binding.recovery)){this.#view=empty('UNAVAILABLE');this.#binding=null;}return this.#view;}
 private prepare(operation:Command['operation'],body:object,key:string,projectId:string|null):object {const scope=this.port.lookup(this.#token)?.scope;if(!scope||typeof key!=='string'||!/^[\x20-\x7e]{1,128}$/.test(key)||/^ *$/.test(key))throw Error('E_PREPARE');const handle=Object.freeze({kind:'e-owned-command'});commands.set(handle,{scope,operation,body:JSON.stringify(body),key,projectId,uncertain:false});return handle;}
 prepareCreate(input:unknown,key:string){const m=metadata(input);if(!m)throw Error('E_METADATA');return this.prepare('create-project',{...header,idempotencyKey:key,metadata:m},key,null);}
 prepareUpdate(input:unknown,key:string){const current=this.view().project,m=metadata(input);if(!current||current.lifecycle!=='active'||!m)throw Error('E_METADATA');return this.prepare('update-metadata',{...header,projectId:current.projectId,expectedRevision:current.revision,idempotencyKey:key,metadata:m},key,current.projectId);}
 prepareArchive(key:string){const current=this.view().project;if(!current||current.lifecycle!=='active')throw Error('E_PROJECT');return this.prepare('soft-delete-project',{...header,projectId:current.projectId,expectedRevision:current.revision,idempotencyKey:key},key,current.projectId);}
 send(handle:object){return this.command(handle,false);}
 reconcile(handle:object){return this.command(handle,true);}
 private command(handle:object,status:boolean){const c=commands.get(handle),binding=this.port.lookup(this.#token);if(!c){this.#view=empty('INVALID_REQUEST');return Promise.resolve(this.#view);}if(!binding||binding.scope!==c.scope){this.#view=empty(binding?'FORBIDDEN':'AUTH_REQUIRED');return Promise.resolve(this.#view);}if(c.uncertain&&!status){this.#view=empty('UNKNOWN_OUTCOME');return Promise.resolve(this.#view);}return this.request('/c-test/v1/'+(status?'status':'commands')+'/'+c.operation,c);}
 list(cursor:string|null=null,limit=2){return this.page('/c-test/v1/projects',cursor,limit);}
 open(projectId:string){if(!hasEntityIdShape(projectId,'project')){this.#view=empty('INVALID_REQUEST');return Promise.resolve(this.#view);}return this.request('/c-test/v1/projects/'+projectId+'?version=1',undefined,false,'project',projectId);}
 history(projectId:string,cursor:string|null=null,limit=2){if(!hasEntityIdShape(projectId,'project')){this.#view=empty('INVALID_REQUEST');return Promise.resolve(this.#view);}return this.page('/c-test/v1/projects/'+projectId+'/history',cursor,limit,projectId);}
 private page(path:string,cursor:string|null,limit:number,projectId:string|null=null){if(!Number.isInteger(limit)||limit<1||limit>4||cursor!==null&&(typeof cursor!=='string'||cursor.length>256)){this.#view=empty('INVALID_REQUEST');return Promise.resolve(this.#view);}return this.request(path+'?version=1&limit='+limit+(cursor===null?'':'&cursor='+encodeURIComponent(cursor)),undefined,cursor!==null,projectId===null?'page':'history',projectId);}
 private async request(path:string,command?:Command,cursor=false,expected:'project'|'page'|'history'='page',projectId:string|null=null):Promise<EView>{
  const sequence=++this.#request,epoch=this.#epoch,token=this.#token,binding=this.port.lookup(token);this.#active?.abort();this.#binding=null;this.#view=empty('LOADING');const publish=(phase:EPhase)=>{const v=empty(phase);if(sequence===this.#request&&epoch===this.#epoch)this.#view=v;return v;};
  if(!binding)return publish('AUTH_REQUIRED');if(!this.port.ready())return publish('UNAVAILABLE');const controller=new AbortController();this.#active=controller;const timer=setTimeout(()=>controller.abort(),this.timeoutMs);if(command)command.uncertain=true;
  try{
   const response=await fetch(this.port.origin+path,{method:command?'POST':'GET',headers:command?{Authorization:'Bearer '+token,Origin:this.port.origin,'Content-Type':'application/json','x-test-decoder-profile':'zarya.p04.r1.conformance.test/v0'}:{Authorization:'Bearer '+token},body:command?.body,signal:controller.signal});
   const value=await readEReply(response);if(sequence!==this.#request||epoch!==this.#epoch)return empty('IGNORED');const live=this.port.lookup(token);if(!live||live.identity!==binding.identity||live.scope!==binding.scope)return publish('AUTH_REQUIRED');if(!this.port.ready()||live.recovery!==binding.recovery)return publish('UNAVAILABLE');
   if(response.status!==200){const e=own(value);if(response.status===401)return publish('AUTH_REQUIRED');if(response.status===403)return publish('FORBIDDEN');if(cursor&&(response.status===400||e?.error==='C_LIST_CHANGED'))return publish('LIST_INVALIDATED');if(response.status===409)return publish('CONFLICT');if(response.status===400||response.status===422)return publish('INVALID_REQUEST');return publish(command?'UNKNOWN_OUTCOME':'UNAVAILABLE');}
   const answer=inspectEAnswer(value);if(!answer||answer.kind!==(command?'committed':expected)||answer.kind==='project'&&answer.project.projectId!==projectId||answer.kind==='history'&&answer.revisions.some(r=>r.revision.projectId!==projectId))return publish(command?'UNKNOWN_OUTCOME':'INVALID_RESPONSE');let result:EView;
   if(answer.kind==='committed'){if(!command||answer.receipt.operation!==command.operation||answer.receipt.idempotencyKey!==command.key||command.projectId!==null&&answer.receipt.projectId!==command.projectId)return publish('UNKNOWN_OUTCOME');command.uncertain=false;result=Object.freeze({...empty('COMMITTED'),receipt:answer.receipt});}
   else if(answer.kind==='project'){if(command)return publish('UNKNOWN_OUTCOME');result=Object.freeze({...empty('READY'),project:answer.project});}
   else if(answer.kind==='page'){if(command)return publish('UNKNOWN_OUTCOME');result=Object.freeze({...empty('READY'),projects:answer.projects,cursor:answer.cursor});}
   else {if(command)return publish('UNKNOWN_OUTCOME');result=Object.freeze({...empty('READY'),revisions:answer.revisions,cursor:answer.cursor});}
   this.#binding=live;this.#view=result;return result;
  }catch{if(sequence!==this.#request||epoch!==this.#epoch)return empty('IGNORED');const live=this.port.lookup(token);return publish(!live||live.identity!==binding.identity?'AUTH_REQUIRED':command?'UNKNOWN_OUTCOME':'UNAVAILABLE');}
  finally{clearTimeout(timer);if(this.#active===controller)this.#active=null;}
 }
}
